const masuk = $input.all().map(function(i){ return i.json; });
const b = (masuk[0] && (masuk[0].body || masuk[0])) || {};
const daftar = Array.isArray(b.confirmations) ? b.confirmations : [];
if (!daftar.length) return [{ json:{ _kosong:true, pesan:'Tidak ada confirmations pada muatan.' } }];
return daftar.map(function(c){
  const lolos = String(c.result||'').toLowerCase()==='verified';
  return { json:{
    request_key:String(c.request_key||''), vendor:String(c.vendor||''),
    hasil_telepon: lolos ? 'verified' : 'failed',
    callback_by:String(c.called_by||''), callback_number_used:String(c.number_used||''),
    catatan:String(c.note||''),
    bank_name:String(c.bank_name||''), account_number:String(c.account_number||''),
    account_name:String(c.account_name||''),
    decided_on:new Date().toISOString().slice(0,10)
  }};
});

const semua = $('Kumpulkan Hasil Telepon').all().map(function(i){ return i.json; });
const lolos = semua.filter(function(r){ return r.hasil_telepon==='verified'; });
const gagal = semua.filter(function(r){ return r.hasil_telepon!=='verified'; });
let diterapkan = [];
try { diterapkan = $('Terapkan Rekening Baru').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { diterapkan = []; }
return [{ json:{
  diproses: semua.length, lolos: lolos.length, gagal: gagal.length,
  master_diterapkan: diterapkan.length,
  daftar_gagal: gagal.map(function(r){ return { req:r.request_key, vendor:r.vendor, catatan:r.catatan_akhir }; }),
  ringkas: lolos.length+' terverifikasi, '+gagal.length+' GAGAL'
}}];

